window.receiveProjectSource({"path": "test/unit/common/test_feed_onboarding_golden_vectors.py", "lines": ["\"\"\"Reference parity test for the cross-repo golden-vector fixture.", "", "This is the DataLake2 half of the URL-normalization / entry-rung-derivation", "parity guard between this repo and the DataLake-repo onboarding DAG, which", "cannot import DataLake2 code across the py3.9/py3.13 boundary. The DataLake", "repo loads an identical copy of ``feed_onboarding_golden_vectors.json`` and", "asserts its own ported functions against the same cases, so the two copies", "must be edited together -- nothing detects one drifting from the other.", "\"\"\"", "", "from __future__ import annotations", "", "import json", "import re", "from datetime import datetime, timedelta, timezone", "from pathlib import Path", "from typing import Any", "", "import pytest", "", "from common.helpers import scheduling", "from common.utils import url_helpers", "from microservices.feeds.tasks import freshness_sampler", "", "pytestmark = pytest.mark.unit", "", "_FIXTURE_PATH = Path(__file__).resolve().parent / \"fixtures\" / \"feed_onboarding_golden_vectors.json\"", "", "", "_FIXTURE: dict[str, Any] = json.loads(_FIXTURE_PATH.read_text())", "", "", "@pytest.mark.parametrize(", "    \"case\",", "    _FIXTURE[\"url_normalization_cases\"],", "    ids=[case[\"input\"] for case in _FIXTURE[\"url_normalization_cases\"]],", ")", "def test_normalize_url_matches_golden_vector(case: dict[str, Any]) -> None:", "    assert url_helpers.normalize_url(case[\"input\"]) == case[\"expected_execution_url\"]", "", "", "@pytest.mark.parametrize(", "    \"case\",", "    _FIXTURE[\"rung_derivation_cases\"],", "    ids=[str(case[\"gaps_minutes\"]) for case in _FIXTURE[\"rung_derivation_cases\"]],", ")", "def test_seed_index_from_gaps_matches_golden_vector(case: dict[str, Any]) -> None:", "    assert scheduling.seed_index_from_gaps(case[\"gaps_minutes\"]) == case[\"expected_index\"]", "", "", "_DATE_ONLY_RAW_RE = re.compile(r\"\\s*\\d{4}[-/.]\\d{2}[-/.]\\d{2}\\s*\")", "", "", "def _is_trustworthy(", "    date_published: datetime,", "    reference_time: datetime,", "    date_published_raw: str | None = None,", ") -> bool:", "    \"\"\"Re-implements the SQL predicate this guards, for fixture self-check only.", "", "    Mirrors ``freshness_sampler.py``'s ``_STALENESS_SQL`` WHERE clause (the", "    ``date_published`` bounds and the two-arm date-only exclusion). No", "    standalone DataLake2 function exists for this guard, so this is not a", "    parity assertion against production code -- it only catches a", "    transcription error in the fixture itself. The real cross-repo parity", "    assertion is added once the guard is ported to Python in the DataLake", "    repo.", "", "    :param date_published: Candidate publish timestamp; must be offset-aware.", "    :param reference_time: The instant the row was ingested, standing in for", "        the SQL predicate's ``created_at`` anchor; must be offset-aware.", "    :param date_published_raw: The publisher's unparsed timestamp string, or", "        ``None`` for a row captured before that value was stored. An empty or", "        whitespace-only string is treated the same as ``None``.", "    :return: ``True`` when the timestamp passes the ``date_published`` bounds", "        and the date-only exclusion. The onboarding-backfill predicate is not", "        mirrored here -- the fixture carries no feed ``created_at``.", "    \"\"\"", "    # A naive value would make the midnight-UTC check below depend on the", "    # runner's local zone, so require the offset rather than guessing it.", "    assert date_published.tzinfo is not None, \"date_published must be offset-aware\"", "    assert reference_time.tzinfo is not None, \"reference_time must be offset-aware\"", "", "    if date_published >= reference_time - timedelta(minutes=5):", "        return False", "    if date_published <= reference_time - timedelta(days=14):", "        return False", "    # A blank string carries no more signal than a missing one, so it must not", "    # win the raw arm just for being non-None.", "    if date_published_raw is not None and date_published_raw.strip():", "        return _DATE_ONLY_RAW_RE.fullmatch(date_published_raw) is None", "    if date_published.astimezone(timezone.utc).time() == datetime.min.time():", "        return False", "    return True", "", "", "@pytest.mark.parametrize(", "    \"case\",", "    _FIXTURE[\"trustworthy_timestamp_cases\"],", "    ids=[case[\"date_published\"] for case in _FIXTURE[\"trustworthy_timestamp_cases\"]],", ")", "def test_trustworthy_timestamp_guard_matches_golden_vector(case: dict[str, Any]) -> None:", "    # Take the fixture's documented Z -> +00:00 path, not py3.11+ native 'Z'", "    # parsing, so this side exercises what the py3.9 sibling consumer must do.", "    date_published = datetime.fromisoformat(case[\"date_published\"].replace(\"Z\", \"+00:00\"))", "    reference_time = datetime.fromisoformat(case[\"reference_time\"].replace(\"Z\", \"+00:00\"))", "    assert _is_trustworthy(date_published, reference_time) == case[\"expected_trustworthy\"]", "", "", "@pytest.mark.parametrize(", "    \"case\",", "    _FIXTURE[\"trustworthy_timestamp_raw_cases\"],", "    ids=[case[\"date_published_raw\"] for case in _FIXTURE[\"trustworthy_timestamp_raw_cases\"]],", ")", "def test_trustworthy_timestamp_raw_arm_matches_golden_vector(case: dict[str, Any]) -> None:", "    \"\"\"The raw arm decides on the publisher's own string, not on the parsed value.", "", "    Includes the cases the midnight-UTC arm alone gets wrong -- an explicit", "    midnight that is real, and a date-only value that parsed to a non-midnight", "    time -- plus the blank-string cases that must fall back to that arm rather", "    than be trusted for being non-null.", "    \"\"\"", "    date_published = datetime.fromisoformat(case[\"date_published\"].replace(\"Z\", \"+00:00\"))", "    reference_time = datetime.fromisoformat(case[\"reference_time\"].replace(\"Z\", \"+00:00\"))", "    assert (", "        _is_trustworthy(date_published, reference_time, case[\"date_published_raw\"])", "        == case[\"expected_trustworthy\"]", "    )", "", "", "_PLACEMENT_CASES: list[dict[str, Any]] = _FIXTURE[\"placement_cases\"]", "", "", "def test_fixture_carries_the_placement_algorithm_version() -> None:", "    \"\"\"The version ties a vector set to the algorithm that produced it, and is", "    the same value ``feeds.feed_schedule_history.algorithm_version`` stores per", "    wave. Without it a past wave cannot be explained once the buckets move on.", "    \"\"\"", "    assert isinstance(_FIXTURE[\"placement_algorithm_version\"], str)", "    assert _FIXTURE[\"placement_algorithm_version\"].strip()", "    assert _FIXTURE[\"publication_bucket_fallback\"] in {", "        bucket[\"name\"] for bucket in _FIXTURE[\"publication_bucket_definitions\"]", "    }", "    assert _FIXTURE[\"publication_bucket_min_articles\"] > 0", "    assert _FIXTURE[\"max_bucket_earliness_minutes\"] > 0", "", "", "def test_placement_cases_cover_every_bucket_the_fallback_and_both_dst_offsets() -> None:", "    \"\"\"DataLake2 has no assigner, so this side cannot recompute placement --", "    what it can do is fail loudly on a fixture that has gone stale or lost a", "    case, rather than passing vacuously.", "    \"\"\"", "    defined = {bucket[\"name\"] for bucket in _FIXTURE[\"publication_bucket_definitions\"]}", "    offsets = {\"EST\", \"EDT\"}", "", "    # The full matrix, not its margins: a bucket-only and an offset-only check both", "    # still pass when a single bucket-offset pair goes missing from the fixture.", "    assert {(case[\"effective_bucket\"], case[\"us_eastern_offset\"]) for case in _PLACEMENT_CASES} == {", "        (bucket, offset) for bucket in defined for offset in offsets", "    }", "", "    # An unmeasured domain must be represented under both offsets and must land on", "    # the fallback -- landing anywhere else is the failure this case exists to catch.", "    unmeasured = [case for case in _PLACEMENT_CASES if case[\"domain_bucket\"] is None]", "    assert {case[\"us_eastern_offset\"] for case in unmeasured} == offsets", "    for case in unmeasured:", "        assert case[\"effective_bucket\"] == _FIXTURE[\"publication_bucket_fallback\"]", "", "    # A measured domain keeps its own bucket rather than silently falling back.", "    for case in _PLACEMENT_CASES:", "        if case[\"domain_bucket\"] is not None:", "            assert case[\"effective_bucket\"] == case[\"domain_bucket\"]", "", "", "def test_each_placement_case_carries_its_own_buckets_target() -> None:", "    \"\"\"``bucket_target_time_et`` is the attractor the sweep slot was placed", "    against, so a case quoting a target its bucket does not define describes a", "    placement no bucket definition explains.", "    \"\"\"", "    target_by_name = {", "        bucket[\"name\"]: bucket[\"target_sweep_time_et\"]", "        for bucket in _FIXTURE[\"publication_bucket_definitions\"]", "    }", "    for case in _PLACEMENT_CASES:", "        assert case[\"bucket_target_time_et\"] == target_by_name[case[\"effective_bucket\"]]", "", "", "def test_bucket_definitions_partition_the_representative_hour_range() -> None:", "    \"\"\"The boundaries are the load-bearing input to classification: exactly one", "    open-ended bucket may exist, and it must be the fallback, or an unmeasured", "    domain has no bucket to land in.", "    \"\"\"", "    definitions = _FIXTURE[\"publication_bucket_definitions\"]", "    open_ended = [b for b in definitions if b[\"max_representative_hour_et\"] is None]", "    assert len(open_ended) == 1", "    assert open_ended[0][\"name\"] == _FIXTURE[\"publication_bucket_fallback\"]", "", "    bounded = [b[\"max_representative_hour_et\"] for b in definitions if b is not open_ended[0]]", "    assert bounded == sorted(bounded)", "    assert len(set(bounded)) == len(bounded)", "", "", "@pytest.mark.parametrize(", "    \"case\",", "    _PLACEMENT_CASES,", "    ids=[", "        f\"{case['us_eastern_offset']}-{case['effective_bucket']}\"", "        f\"{'-unmeasured' if case['domain_bucket'] is None else ''}\"", "        for case in _PLACEMENT_CASES", "    ],", ")", "def test_placement_case_is_internally_consistent(case: dict[str, Any]) -> None:", "    \"\"\"The derived contract DataLake2 depends on: ``next_run_at`` is the", "    earliest slot, and ``scrape_schedule`` is those same slots collapsed onto", "    one shared minute. A regenerated fixture that broke either would feed the", "    dispatcher a cron disagreeing with its own placement.", "    \"\"\"", "    slots = [datetime.fromisoformat(slot.replace(\"Z\", \"+00:00\")) for slot in case[\"expected_slots\"]]", "    next_run_at = datetime.fromisoformat(case[\"expected_next_run_at\"].replace(\"Z\", \"+00:00\"))", "", "    assert slots", "    assert next_run_at == min(slots)", "    assert len({slot.minute for slot in slots}) == 1", "", "    minute_field, hours_field = case[\"expected_scrape_schedule\"].split(\" \")[:2]", "    assert int(minute_field) == slots[0].minute", "    assert [int(hour) for hour in hours_field.split(\",\")] == sorted({slot.hour for slot in slots})", "", "", "# ----- the guard as SQL text, for consumers that re-issue it ---------------", "", "", "_SQL_GUARDS: dict[str, Any] = _FIXTURE[\"trustworthy_timestamp_sql_guards\"]", "", "", "def _normalize_sql(sql: str) -> str:", "    \"\"\"Collapse runs of whitespace so a fragment matches across line breaks.", "", "    :param sql: SQL text as written.", "    :return: The same text with every whitespace run reduced to one space.", "    \"\"\"", "    return \" \".join(sql.split())", "", "", "def test_sql_guard_patterns_are_the_ones_the_sampler_compiles() -> None:", "    \"\"\"The two POSIX patterns are interpolated into the predicate, so a fixture", "    carrying different ones would export a guard nothing actually runs.\"\"\"", "    assert _SQL_GUARDS[\"blank_raw_pattern\"] == freshness_sampler._BLANK_RAW_PATTERN", "    assert _SQL_GUARDS[\"date_only_raw_pattern\"] == freshness_sampler._DATE_ONLY_RAW_PATTERN", "", "", "@pytest.mark.parametrize(", "    \"fragment\",", "    _SQL_GUARDS[\"required_fragments\"],", "    ids=range(len(_SQL_GUARDS[\"required_fragments\"])),", ")", "def test_staleness_sql_carries_every_exported_guard_fragment(fragment: str) -> None:", "    \"\"\"_STALENESS_SQL is the authoritative definition of a trustworthy row.", "", "    Consumers in other repositories re-issue these fragments verbatim against", "    the same tables; a fragment dropped or reworded here silently leaves them", "    measuring a population this repo no longer considers trustworthy.", "    \"\"\"", "    assert fragment in _normalize_sql(str(freshness_sampler._STALENESS_SQL))", "", "", "def test_exported_guards_include_the_onboarding_backfill_exclusion() -> None:", "    \"\"\"The two arms most easily lost by a consumer copying an older draft: the", "    raw date-only test, and the exclusion of a feed's first-scrape backfill.\"\"\"", "    fragments = _SQL_GUARDS[\"required_fragments\"]", "    assert any(\"za.date_published > f.created_at\" == fragment for fragment in fragments)", "    assert any(\"date_published_raw\" in fragment for fragment in fragments)"], "blocks": [{"start": 1, "end": 32, "label": "Imports and module setup"}, {"start": 33, "end": 41, "label": "def test_normalize_url_matches_golden_vector"}, {"start": 42, "end": 53, "label": "def test_seed_index_from_gaps_matches_golden_vector"}, {"start": 54, "end": 96, "label": "def _is_trustworthy"}, {"start": 97, "end": 109, "label": "def test_trustworthy_timestamp_guard_matches_golden_vector"}, {"start": 110, "end": 133, "label": "def test_trustworthy_timestamp_raw_arm_matches_golden_vector"}, {"start": 134, "end": 147, "label": "def test_fixture_carries_the_placement_algorithm_version"}, {"start": 148, "end": 174, "label": "def test_placement_cases_cover_every_bucket_the_fallback_and_both_dst_offsets"}, {"start": 175, "end": 187, "label": "def test_each_placement_case_carries_its_own_buckets_target"}, {"start": 188, "end": 202, "label": "def test_bucket_definitions_partition_the_representative_hour_range"}, {"start": 203, "end": 235, "label": "def test_placement_case_is_internally_consistent"}, {"start": 236, "end": 244, "label": "def _normalize_sql"}, {"start": 245, "end": 251, "label": "def test_sql_guard_patterns_are_the_ones_the_sampler_compiles"}, {"start": 252, "end": 266, "label": "def test_staleness_sql_carries_every_exported_guard_fragment"}, {"start": 267, "end": 272, "label": "def test_exported_guards_include_the_onboarding_backfill_exclusion"}], "lineCount": 272, "sha256": "fa547bf2df1a374c49f2d5bf138b7fd9a89cad8678c3087f69360e54b7dda398", "endsWithNewline": true});
